    title: "Khả năng tiếp cận",
    level: 3,
    parent_id: {
      $oid: "68051ee0b3a0b79715d264e3",
    },
    description:
      "Khả năng truy cập trang web là hoạt động thiết kế và phát triển các trang web mà mọi người, bao gồm cả người khuyết tật, có thể sử dụng. Hoạt động này bao gồm việc triển khai các tính năng và tiêu chuẩn giúp nội dung web dễ nhận biết, dễ vận hành, dễ hiểu và mạnh mẽ đối với tất cả người dùng, bất kể khả năng thể chất hay nhận thức của họ. Điều này bao gồm cung cấp các lựa chọn thay thế văn bản cho hình ảnh, đảm bảo điều hướng bằng bàn phím, sử dụng độ tương phản màu đủ, cung cấp phụ đề cho nội dung âm thanh và tạo bố cục nhất quán và dễ đoán. Việc tuân thủ các nguyên tắc về khả năng truy cập không chỉ cải thiện khả năng sử dụng cho người khuyết tật mà còn nâng cao trải nghiệm người dùng tổng thể cho tất cả khách truy cập, đồng thời có khả năng tăng phạm vi tiếp cận và tuân thủ pháp luật của trang web.",
