    description:
      "GitHub đã trở thành trung tâm cho các dự án mã nguồn mở và được các nhà phát triển, công ty và tổ chức sử dụng rộng rãi cho cả kho lưu trữ riêng tư và công cộng. GitHub đã được Microsoft mua lại vào năm 2018 nhưng vẫn tiếp tục hoạt động như một thực thể tương đối độc lập. Sự phổ biến của GitHub đã biến nó thành một công cụ thiết yếu trong quy trình phát triển phần mềm hiện đại và là nền tảng chính để giới thiệu các dự án mã hóa và đóng góp cho phần mềm mã nguồn mở.",
