    description:
      "Eleventy (11ty) là trình tạo trang tĩnh dễ sử dụng, dễ tùy chỉnh, hiệu suất cao và mạnh mẽ với một bộ plugin hữu ích (ví dụ: điều hướng, chuyển đổi hình ảnh thời gian xây dựng, tài sản bộ nhớ đệm). Các trang có thể được xây dựng và viết bằng nhiều ngôn ngữ mẫu khác nhau (HTML, Markdown, JavaScript, Liquid, Nunjucks, Handlebars, Mustache, EJS, Haml, Pug hoặc JS template literals). Nhưng nó cũng cung cấp khả năng tạo trang động từ dữ liệu cục bộ hoặc các nguồn bên ngoài được biên dịch tại thời điểm xây dựng. Nó không có bất kỳ sự phụ thuộc nào vào JavaScript phía máy khách.",
