    title: "CSS",
    level: 2,
    parent_id: {
      $oid: "6804a58a2f5a3a769de61906",
    },
    description:
      "CSS (Cascading Style Sheets) là ngôn ngữ định kiểu được sử dụng để mô tả cách trình bày tài liệu được viết bằng HTML hoặc XML. Nó định nghĩa cách các thành phần sẽ được hiển thị trên màn hình, trên giấy hoặc trong các phương tiện khác. CSS tách biệt thiết kế khỏi nội dung, cho phép linh hoạt hơn và kiểm soát bố cục, màu sắc và phông chữ của các trang web. Nó sử dụng một hệ thống bộ chọn để nhắm mục tiêu vào các thành phần HTML và áp dụng các kiểu cho chúng. CSS hỗ trợ thiết kế đáp ứng thông qua các truy vấn phương tiện, cho phép tạo các bố cục thích ứng với các kích thước màn hình và thiết bị khác nhau. Cascade, kế thừa và tính đặc hiệu là các khái niệm chính trong CSS xác định cách áp dụng các kiểu khi nhiều quy tắc nhắm mục tiêu vào cùng một thành phần. CSS hiện đại bao gồm các tính năng như Flexbox và Grid để kiểm soát bố cục nâng cao, hoạt ảnh và chuyển tiếp để tạo giao diện người dùng động.",
