    title: "Trình tạo trang tĩnh",
    level: 2,
    parent_id: {
      $oid: "6804a58a2f5a3a769de61906",
    },
    description:
      "Trình tạo trang tĩnh (SSG) là các công cụ tạo trang web HTML từ dữ liệu thô và mẫu, tạo ra các trang được kết xuất trước tại thời điểm xây dựng thay vì tại thời điểm chạy. Chúng kết hợp các lợi ích của trang web tĩnh (tốc độ, bảo mật, đơn giản) với tính linh hoạt của trang web động. SSG thường sử dụng ngôn ngữ đánh dấu như Markdown cho nội dung, công cụ tạo mẫu cho bố cục và tạo trang web hoàn toàn tĩnh có thể được lưu trữ trên máy chủ web đơn giản hoặc mạng phân phối nội dung. Các SSG phổ biến bao gồm Jekyll, Hugo, Gatsby và Eleventy. Chúng rất phù hợp cho blog, trang web tài liệu và trang web tập trung vào nội dung. SSG cung cấp các lợi thế về hiệu suất, tích hợp kiểm soát phiên bản và giảm độ phức tạp ở phía máy chủ, khiến chúng ngày càng phổ biến cho nhiều dự án web.",
