    description:
      "Document Object Model (DOM) là một giao diện lập trình được xây dựng cho các tài liệu HTML và XML. Nó đại diện cho trang cho phép các chương trình và tập lệnh cập nhật động cấu trúc, nội dung và kiểu tài liệu. Với DOM, chúng ta có thể dễ dàng truy cập và thao tác các thẻ, ID, lớp, thuộc tính, v.v.",
