    title: "HTTPS",
    level: 3,
    parent_id: {
      $oid: "680659da638b10eada619f05",
    },
    description:
      "Giao thức truyền siêu văn bản an toàn (HTTPS) là phiên bản an toàn của HTTP, là giao thức chính được sử dụng để gửi dữ liệu giữa trình duyệt web và trang web. HTTPS được mã hóa để tăng tính bảo mật khi truyền dữ liệu. Điều này đặc biệt quan trọng khi người dùng truyền dữ liệu nhạy cảm, chẳng hạn như bằng cách đăng nhập vào tài khoản ngân hàng, dịch vụ email hoặc nhà cung cấp bảo hiểm y tế.",
