    description:
      'Astro là một trình tạo trang tĩnh (SSG) hiện đại và khung web được thiết kế để xây dựng các trang web nhanh, tập trung vào nội dung. Nó cho phép các nhà phát triển sử dụng nhiều khung giao diện người dùng (như React, Vue hoặc Svelte) trong cùng một dự án, tự động kết xuất các thành phần thành HTML tĩnh tại thời điểm xây dựng. Phương pháp "hydrat hóa một phần" độc đáo của Astro chỉ gửi JavaScript đến trình duyệt khi cần thiết, dẫn đến kích thước gói nhỏ hơn đáng kể và thời gian tải nhanh hơn. Khung hỗ trợ định tuyến dựa trên tệp, nội dung đánh dấu và tối ưu hóa tích hợp cho hình ảnh và tài sản. Kiến trúc đảo thành phần của Astro cho phép các nhà phát triển tạo các thành phần tương tác trong khi vẫn duy trì các lợi ích về hiệu suất của HTML tĩnh, khiến nó đặc biệt phù hợp với các trang web giàu nội dung như blog, tài liệu và trang tiếp thị.',
